const input = $input.first().json;
const payload = input.body ?? input;

if (!payload || typeof payload !== 'object') {
  throw new Error('Payload vacío o inválido');
}

if (!['firing', 'resolved'].includes(payload.status)) {
  throw new Error(
    `Estado de Alertmanager no válido: ${payload.status}`
  );
}

if (!Array.isArray(payload.alerts)) {
  throw new Error('El payload no contiene el array alerts');
}

const alerts = payload.alerts;

if (alerts.length === 0) {
  return [];
}

const escapeHtml = (value) =>
  String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;');

const first = alerts[0] ?? {};
const commonLabels = payload.commonLabels ?? {};
const commonAnnotations = payload.commonAnnotations ?? {};

const status = payload.status;
const severity =
  commonLabels.severity ??
  first.labels?.severity ??
  'unknown';

const severityNames = {
  critical: 'CRÍTICA',
  warning: 'AVISO',
  info: 'INFORMATIVA',
  unknown: 'SIN CLASIFICAR',
};

const severityIcons = {
  critical: '🔴',
  warning: '🟠',
  info: '🔵',
  unknown: '⚪',
};

const groupKey = payload.groupKey ?? 'sin-group-key';

const fingerprints = alerts
  .map((alert) => alert.fingerprint)
  .filter(Boolean)
  .sort()
  .join(',');

const dedupKey = `${status}:${groupKey}:${fingerprints}`;
const staticData = $getWorkflowStaticData('global');
const now = Date.now();

staticData.recentNotifications ??= {};

for (const [key, timestamp] of Object.entries(
  staticData.recentNotifications
)) {
  if (now - timestamp > 10 * 60 * 1000) {
    delete staticData.recentNotifications[key];
  }
}

const previousTimestamp =
  staticData.recentNotifications[dedupKey];

if (
  previousTimestamp &&
  now - previousTimestamp < 60 * 1000
) {
  return [];
}

staticData.recentNotifications[dedupKey] = now;

const formatDate = (value) => {
  if (!value) return null;

  const date = new Date(value);

  if (Number.isNaN(date.getTime())) return null;

  return date.toLocaleString('es-ES', {
    timeZone: 'Atlantic/Canary',
    dateStyle: 'short',
    timeStyle: 'medium',
  });
};

const header =
  status === 'firing'
    ? '🚨 <b>ALERTA TÉCNICA ACTIVA</b>'
    : '✅ <b>ALERTA TÉCNICA RESUELTA</b>';

const lines = [
  header,
  '',
  `${severityIcons[severity] ?? severityIcons.unknown} ` +
    `<b>Severidad:</b> ` +
    `${escapeHtml(severityNames[severity] ?? severity.toUpperCase())}`,
  `<b>Número de alertas:</b> ${alerts.length}`,
];

const groupSummary =
  commonAnnotations.summary ??
  first.annotations?.summary;

if (groupSummary) {
  lines.push(
    `<b>Resumen:</b> ${escapeHtml(groupSummary)}`
  );
}

for (const [index, alert] of alerts.slice(0, 10).entries()) {
  const labels = alert.labels ?? {};
  const annotations = alert.annotations ?? {};

  const alertName =
    labels.alertname ??
    `Alerta ${index + 1}`;

  const service =
    labels.service ??
    labels.deployment ??
    labels.job ??
    labels.container;

  const location = [
    labels.namespace,
    labels.pod,
  ]
    .filter(Boolean)
    .join(' / ');

  const description =
    annotations.description ??
    annotations.summary ??
    'Sin descripción';

  lines.push('');
  lines.push(
    `<b>${index + 1}. ${escapeHtml(alertName)}</b>`
  );

  if (service) {
    lines.push(
      `<b>Servicio:</b> ${escapeHtml(service)}`
    );
  }

  if (location) {
    lines.push(
      `<b>Ubicación:</b> ${escapeHtml(location)}`
    );
  }

  lines.push(
    `<b>Detalle:</b> ${escapeHtml(description)}`
  );

  const start = formatDate(alert.startsAt);
  const end = formatDate(alert.endsAt);

  if (start) {
    lines.push(`<b>Inicio:</b> ${escapeHtml(start)}`);
  }

  if (status === 'resolved' && end) {
    lines.push(`<b>Fin:</b> ${escapeHtml(end)}`);
  }
}

if (alerts.length > 10) {
  lines.push('');
  lines.push(
    `<i>Se han omitido ${alerts.length - 10} alertas adicionales.</i>`
  );
}

lines.push('');
lines.push('<i>Origen: Prometheus → Alertmanager → n8n</i>');

return [
  {
    json: {
      message: lines.join('\n'),
      alertStatus: status,
      severity,
      groupKey,
      fingerprints,
      alertCount: alerts.length,
      dedupKey,
    },
  },
];
